export default "<!doctype html><html lang=\"en\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Side Quest Dash</title>\n<style>\n*{box-sizing:border-box}body{margin:0;background:#111d33;color:#eaf5ff;font:16px/1.4 system-ui}main{max-width:1220px;margin:auto;padding:clamp(12px,3vw,32px)}h1,h2,p{margin:0}h1{font-size:clamp(34px,6vw,54px);line-height:1}header{margin-bottom:14px}header p,a{color:#a5f3fc}header p{margin-top:6px}.layout{display:grid;grid-template-columns:minmax(0,1fr) 260px;gap:14px;align-items:start}.stage,aside{border:1px solid #486284;border-radius:12px;overflow:hidden;background:#192a43}canvas{display:block;width:100%;height:auto;image-rendering:pixelated}aside{padding:14px;display:grid;gap:11px}h2{font-size:19px}aside p,footer{font-size:13px}.roster{display:grid;grid-template-columns:repeat(4,1fr);gap:5px}button{border:1px solid #647b9a;border-radius:8px;background:#223b5a;color:white;min-height:44px;cursor:pointer;font:inherit}button:focus-visible,canvas:focus-visible{outline:3px solid #fde68a;outline-offset:-3px}.roster button[aria-pressed=true]{border:2px solid #67e8f9;background:#275772}.roster img{display:block;width:40px;height:40px;image-rendering:pixelated;margin:auto}#start{background:#a5f3fc;color:#132642;font-weight:750}footer{padding-top:12px}.touch{display:none;justify-content:space-between;padding:8px;gap:6px}.touch button{min-width:44px;touch-action:none}.touch div{display:flex;gap:6px}@media(pointer:coarse){.touch{display:flex}}@media(max-width:740px){.layout{grid-template-columns:1fr}}\n\n.stage{position:relative}.stage:fullscreen,.stage.expanded{background:#101b30;display:flex;flex-direction:column;align-items:center;justify-content:center;border:0;border-radius:0}\n.stage.expanded{position:fixed;inset:0;z-index:5}\n.stage:fullscreen canvas,.stage.expanded canvas{width:min(100%, calc((100dvh - 110px) * 1.73913));height:auto;object-fit:contain}\n.stage:fullscreen .touch,.stage.expanded .touch{width:min(100%,800px)}\n.stage-tools{display:flex;justify-content:space-between;align-items:center;width:100%;padding:6px 12px;font-size:13px;color:#dbeafe}\n.level-marker{display:flex;align-items:center;gap:8px}.level-marker img{image-rendering:pixelated}.stage-tools button{padding:4px 12px}@media(pointer:coarse),(max-width:560px){.stage-tools > span:nth-child(2){display:none}}\n.stage-tools[hidden],.lesson[hidden]{display:none}\n.lesson{position:absolute;inset:0;z-index:2;background:#0d1a2bc4;display:grid;place-items:center;padding:12px;overflow:auto}\n.lesson-card{width:min(100%,480px);padding:20px;background:#182c48;border:1px solid #7c9cbf;border-radius:14px;display:grid;gap:10px;box-shadow:0 10px 35px #0006}\n.lesson-actions{display:flex;gap:8px;flex-wrap:wrap}.lesson-actions button{padding:6px 14px}\n#lesson-next{background:#a5f3fc;color:#132642;font-weight:750}.lesson-kicker{color:#a5f3fc;font-size:13px}\n.lesson-art{display:flex;gap:12px}.lesson-art img{width:43px;height:43px;object-fit:contain;image-rendering:pixelated}\n\n.stage-actions{display:flex;gap:4px}.stage-actions button{white-space:nowrap;padding-inline:8px}\n.maze-controls,.maze-hint,.stage.maze .platform-hint{display:none}.stage.maze .maze-hint{display:inline}.stage.maze .normal-controls{display:none}\n@media(pointer:coarse){.stage.maze .maze-controls{display:flex}.stage.maze .maze-hint{display:none}}\n#report{max-width:min(670px,calc(100% - 24px));max-height:90dvh;overflow:auto;border:1px solid #6b8ab1;border-radius:14px;background:#172944;color:#eff6ff;padding:22px}\n#report::backdrop{background:#0d1a2bdc}#report form{display:grid;gap:12px}\n#report label{display:grid;gap:4px}#report textarea{width:100%;min-height:54px;border:1px solid #7793b8;border-radius:7px;padding:8px;background:#fff;color:#16243b;font:inherit;resize:vertical}\n#report .actions{display:flex;flex-wrap:wrap;gap:8px}#report button{padding:6px 12px}#printable{display:none}\n@media print{\n @page{margin:15mm}\n body{background:white;color:#142139}body>*{display:none!important}\n body>#printable{display:block!important;font:11pt/1.42 system-ui}\n #printable h1{font-size:23pt}#printable h2{font-size:15pt;margin:10pt 0 6pt}\n .print-answer{white-space:pre-wrap;min-height:17pt;border-bottom:1px solid #b8c0cc;margin:4pt 0 9pt;overflow-wrap:anywhere}\n .print-question{break-inside:avoid}.handout{break-before:page}.handout p{margin:8pt 0}\n #printable a{color:#143b68}\n}\n\n.demo-picker[hidden]{display:none}.demo-picker{border-top:1px solid #4f6b90;padding-top:10px;display:grid;gap:7px}\n.demo-picker button{padding:5px 10px;text-align:left}\n#reflection{display:grid;gap:10px}\n#reflection fieldset{border:1px solid #6884a6;border-radius:8px;margin:0;padding:8px 11px;display:grid;gap:4px;min-width:0}\n#reflection legend{padding:0 5px;font-weight:650}\n#reflection .choice{display:flex;align-items:center;gap:8px;min-height:25px;cursor:pointer}\n#reflection input[type=checkbox],#reflection input[type=radio]{accent-color:#67e8f9}\n#reflection input[type=text]{margin:0 0 4px 24px;width:calc(100% - 24px);padding:6px 8px;border-radius:6px;border:1px solid #7793b8;font:inherit;color:#16243b}\n#reflection [hidden]{display:none!important}\n@media print{.print-answer{border:0;min-height:0;margin:3pt 0 7pt}.print-options{margin:0;padding-left:17pt}.print-options li{margin:0 0 2pt}.print-option{font-weight:600}}\n\n.demo-toolbar{display:flex;gap:7px;align-items:center;justify-content:center;flex-wrap:wrap;width:100%;padding:5px 10px;font-size:13px}\n.demo-toolbar[hidden],.demo-toolbar [hidden]{display:none}.demo-toolbar label{display:flex;align-items:center;gap:6px}\n.demo-toolbar select{background:#233c60;border:1px solid #7c9cbf;border-radius:7px;color:#eff6ff;padding:6px;min-height:38px;max-width:65vw;font:inherit}\n.demo-toolbar button{min-height:38px;padding:4px 9px}.demo-toolbar p{width:100%;text-align:center;color:#cfe2ff}\n.stage.demo canvas{width:min(100%,calc((100dvh - 185px)*1.73913))}\n@media(max-height:540px){.demo-toolbar p{display:none}.stage.demo canvas{width:min(100%,calc((100dvh - 150px)*1.73913))}}\n</style>\n<main><header><h1>Side Quest Dash</h1><p>Jump, explore, and find your way back on track.</p></header><div class=\"layout\">\n<section class=\"stage\" id=\"stage\"><div class=\"stage-tools\" id=\"stage-tools\" hidden><span class=\"level-marker\"><img id=\"level-graphic\" alt=\"\" width=\"36\" height=\"36\"> <span id=\"level-label\">Level 1 / 10</span></span><span class=\"platform-hint\">\u2190 \u2192 Move \u00b7 Space Jump \u00b7 \u2193 Drop</span><span class=\"maze-hint\">\u2191 \u2193 \u2190 \u2192 Move \u00b7 Find both switches</span><div class=\"stage-actions\"><button id=\"sound\" aria-pressed=\"true\">Effects on</button> <button id=\"music\" aria-pressed=\"true\">Music on</button> <button id=\"exit\">Exit</button></div></div><canvas id=\"game\" width=\"800\" height=\"460\" tabindex=\"0\" aria-label=\"Side Quest Dash game\"></canvas>\n<div class=\"demo-toolbar\" id=\"demo-toolbar\" hidden>\n <label>Practice <select id=\"demo-station\" aria-label=\"Practice feature\"></select></label>\n <button id=\"demo-retry\" type=\"button\">Reset</button>\n <button id=\"demo-next\" type=\"button\">Next feature</button>\n <label id=\"demo-power-control\" hidden>Power <select id=\"demo-power\"><option value=\"20\">20% \u00b7 slow</option><option value=\"40\">40% \u00b7 single</option><option value=\"60\">60% \u00b7 double</option><option value=\"85\">85% \u00b7 triple</option></select></label>\n <p id=\"demo-note\"></p>\n</div>\n<div class=\"touch normal-controls\"><div><button data-control=\"left\" aria-label=\"Left\">\u25c0</button><button data-control=\"right\" aria-label=\"Right\">\u25b6</button></div><div><button data-control=\"drop\">Drop</button><button data-control=\"jump\">Jump</button></div></div>\n<div class=\"touch maze-controls\">\n <div><button data-control=\"left\" aria-label=\"Move left\">\u25c0</button><button data-control=\"right\" aria-label=\"Move right\">\u25b6</button></div>\n <div><button data-control=\"jump\" aria-label=\"Move up\">\u25b2</button><button data-control=\"drop\" aria-label=\"Move down\">\u25bc</button></div>\n</div>\n<div class=\"lesson\" id=\"lesson\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"lesson-title\" hidden>\n <div class=\"lesson-card\"><p class=\"lesson-kicker\" id=\"lesson-kicker\"></p><h2 id=\"lesson-title\"></h2>\n <div class=\"lesson-art\" id=\"lesson-art\"></div><p id=\"lesson-text\"></p>\n <div class=\"lesson-actions\"><button id=\"lesson-next\">Next</button><button id=\"lesson-skip\">Skip intro</button></div></div>\n</div></section>\n<aside><h2>Choose your character</h2><div id=\"roster\" class=\"roster\"></div>\n<label><input type=\"checkbox\" id=\"show-instructions\" checked> Show how to play</label>\n<p>Pick a character to open the game full screen.</p>\n<section class=\"demo-picker\" aria-labelledby=\"demo-title\">\n <h2 id=\"demo-title\">Demo Mode</h2><p>Practice any feature without playing through the campaign.</p>\n <button type=\"button\" id=\"demo-level\">Play the feature tour</button>\n <button type=\"button\" id=\"demo-maze\">Play Hyperfocus maze</button>\n</section>\n<p><strong>Move:</strong> \u2190 \u2192 or A / D. <strong>Jump:</strong> Space or \u2191. <strong>Drop:</strong> \u2193 or S.</p></aside></div>\n<footer>Credits \u00b7 Icons by <a href=\"https://icons8.com/\">Icons8</a> \u00b7 <a href=\"https://pixelfrog-assets.itch.io/pixel-adventure-1\">Pixel Adventure art by Pixel Frog</a></footer></main>\n<dialog id=\"report\" aria-labelledby=\"report-title\">\n <form method=\"dialog\">\n  <h2 id=\"report-title\">Your flight scorecard</h2>\n  <p id=\"report-stats\"></p>\n  <p>Choose any answers you like. For the questions about you, you can pick more than one or add your own. You can also print a blank copy.</p>\n  <div id=\"reflection\"></div>\n  <div class=\"actions\"><button type=\"button\" id=\"print-score\">Print scorecard &amp; handout</button><button>Back to start</button></div>\n </form>\n</dialog>\n<section id=\"printable\" aria-label=\"Printable scorecard and handout\">\n <h1>Side Quest Dash \u00b7 My scorecard</h1><p id=\"print-stats\"></p><h2>My reflection</h2><div id=\"print-reflection\"></div>\n <section class=\"handout\"><h1>Side Quest Dash \u00b7 What I learned</h1>\n  <h2>What is dopamine?</h2><p>Dopamine is a messenger in your brain. It helps your brain notice things that matter and learn what you might want to do again. The game\u2019s power meter uses pretend rules. Real life does not have a dopamine percentage meter.</p>\n  <h2>What is a side quest?</h2><p>A side quest is something that catches your attention while you are working on something else. Side quests can be fun. You can pause and decide whether to keep going or save the idea for later.</p>\n  <h2>What is hyperfocus?</h2><p>Hyperfocus is getting so absorbed in something that it can be hard to notice time passing or switch to another task. The maze is a game example of how hard switching can feel. Getting absorbed in an activity can also be enjoyable.</p>\n  <h2>Try this next time</h2><p>Pick one small step you want to take. If a side quest pops up, write it down for later. A timer, a short break, or a reminder from someone you trust can help you switch.</p>\n  <p>Read more with a grown-up: <a href=\"https://irp.nida.nih.gov/wp-content/uploads/2019/12/NIDA_DrugsBrainsAddiction_2018.pdf\">NIH on dopamine and learning</a> \u00b7 <a href=\"https://pmc.ncbi.nlm.nih.gov/articles/PMC7851038/\">Research on hyperfocus</a>.</p>\n </section>\n</section>\n<script src=\"https://routines.getadhd.care/side-quest/assets.js\"></script><script>\nconst SQ_PAID=__SIDEQUEST_PAID__;let sqDeaths=0;\n\n\nconst sprites = Object.fromEntries(Object.entries(assets).map(([key, src]) => {\n  const image = new Image();\n  image.src = src;\n  return [key, image];\n}));\nconst canvas = document.getElementById('game');\nconst ctx = canvas.getContext('2d');\nconst characters = ['Ninja Frog', 'Mask Dude', 'Pink Man', 'Virtual Guy'];\nlet character = characters[0];\nconst controls = {left:false,right:false,jump:false,drop:false};\nconst levels = [\n  {sections:8,ratio:'BBBBT',pace:1,pull:1.5,rest:285,drain:.024},\n  {sections:10,ratio:'BBTBB',second:'BTBBT',pace:1,pull:1.8,rest:230,drain:.028},\n  {sections:12,ratio:'TBTBT',pace:1,pull:2.1,rest:185,drain:.032},\n  {sections:14,ratio:'TTBTT',pace:1,pull:2.4,rest:145,drain:.038},\n  {sections:16,ratio:'TTBTT',pace:1.17,pull:2.9,rest:112,drain:.042},\n  {sections:18,ratio:'TTBTT',pace:1.35,pull:3.45,rest:80,drain:.048},\n  {sections:20,ratio:'TTBTT',pace:1.40,pull:3.65,rest:73,drain:.050},\n  {sections:22,ratio:'TTBTT',pace:1.45,pull:3.85,rest:65,drain:.052},\n  {sections:24,ratio:'TTBTT',pace:1.50,pull:4.0,rest:58,drain:.054},\n  {sections:26,ratio:'TTBTT',pace:1.55,pull:4.2,rest:50,drain:.056}\n];\nif(!SQ_PAID)levels.splice(1);\nlet level = 0, platforms, ground, finishX, course, checkpointLine, springs, rocks, debris, traps;\nconst demoLevel = {...levels[0], drain:.012};\nlet demoMode = null;\nconst currentLevel = () => demoMode==='tour' ? demoLevel : levels[level];\n\nconst themes=[\n [112,0,'#9c5843'],[112,64,'#a75138'],[112,128,'#b58b59'],[288,64,'#a64343'],\n [208,0,'#89504b'],[208,64,'#536474'],[208,128,'#ad6839'],[288,128,'#a79032'],\n [4,0,'#62687a'],[4,128,'#34766d']\n];\nconst trapTypes=['fire','saw','spikes','ball','spikehead','arrow','falling'];\nlet trapOrder=[...trapTypes];\nfunction randomizeTraps(){\n  trapOrder=[...trapTypes];\n  for(let i=trapOrder.length-1;i>0;i--){\n    const j=Math.floor(Math.random()*(i+1));[trapOrder[i],trapOrder[j]]=[trapOrder[j],trapOrder[i]];\n  }\n}\nconst trapTitles={fire:'Flame vent',saw:'Moving saw',spikes:'Ground spikes',ball:'Swinging spiked ball',\n  spikehead:'Spikehead',arrow:'Flying arrow',falling:'Falling platform'};\nconst fanPlatform=(x,y,w=104)=>({x,y,w,baseY:y,topY:107,spikeY:76,solid:false,fan:true,phase:'idle'});\nconst platformY=(p,x)=>p.y+(p.angle?Math.tan(p.angle)*(x-p.x-p.w/2):0);\n\nconst demoStations=[\n  {name:'Boosters, ice & tasks',hint:'Try two quick boosts to stack ice. Complete a task or refill with a steady boost to clear it.'},\n  {name:'Jumps, ledges & pits',hint:'Use the Power menu to try each jump tier. Cross the pit, then press \u2193 or Drop to pass through a ledge.'},\n  {name:'Trampolines & mystery pickups',hint:'Land on all three springs to try a mystery meal, quick boost, and rocket ride.'},\n  {name:'Rockhead',hint:'Approach the hanging Rockhead to make it shake and fall. Watch for the grass spray.'},\n  {name:'Brown & gray rotating platforms',hint:'Jump onto both platforms. Stand near an edge too long and the platform will tip and dump you off.'},\n  {name:'Flame vent & ground spikes',hint:'Wait for the flame to go out, then jump over the spikes.'},\n  {name:'Moving saw & swinging spiked ball',hint:'Watch the timing of the moving saw and the swinging ball before crossing.'},\n  {name:'Spikehead & flying arrows',hint:'Move around Spikehead and time your jump or drop to avoid the arrows.'},\n  {name:'Falling platform',hint:'Land on the platform and jump off before it drops.'},\n  {name:'Side-quest rocket & refocus target',hint:'Let the rocket catch you. Hold Jump to fly, then catch the target or complete a task.'},\n  {name:'Fan platform & ceiling spikes',hint:'Ride the fan as it lifts, then jump or drop off before reaching the ceiling spikes.'},\n  {name:'Hyperfocus maze',hint:'Find both switches and avoid the timed spikes. Use the arrows or touch controls.'}\n];\nlet demoStation=0;\nconst mazeStation=demoStations.length-1;\nconst demoMaze=()=>demoMode==='tour'&&demoStation===mazeStation;\nconst themeIndex=()=>demoMode==='tour'?Math.min(demoStation,themes.length-1):level;\n\nfunction buildDemoCourse(){\n  finishX=705;checkpointLine=368;\n  ground=[];platforms=[];course=[];springs=[];rocks=[];debris=[];traps=[];\n  const addGround=(x,w)=>ground.push({x,w,y:390,solid:true});\n  const pickup=(type,x,variant=0,y=365)=>course.push({type,x,y,variant});\n  const ledge=(x,w,y,extra={})=>platforms.push({x,w,y,solid:false,...extra});\n  const trap=(type,x,phase=0)=>{\n    const hazard={type,x,y:390,phase,lastHit:-100};traps.push(hazard);\n    if(type==='falling')ledge(x-48,96,307,{falling:hazard,angle:0});\n  };\n  if(demoStation===1){addGround(0,305);addGround(365,435);}\n  else addGround(0,800);\n  pickup('fruit',645);\n  switch(demoStation){\n    case 0:\n      pickup('treat',180);pickup('treat',258,1);pickup('task',370);\n      pickup('meal',505);pickup('veg',577,1);break;\n    case 1:\n      ledge(206,106,315);ledge(389,131,306);ledge(525,115,234);\n      pickup('task',459,1,279);pickup('meal',580,0,210);break;\n    case 2:\n      ['booster','depleter','rocket'].forEach((mystery,i)=>springs.push({x:200+i*163,y:390,activated:-100,mystery}));\n      break;\n    case 3:\n      rocks.push({x:335,y:105,ground:390,vy:0,phase:'hanging',age:0,hit:false});\n      pickup('meal',490);break;\n    case 4:\n      ledge(170,136,307,{rotating:true,angle:0,angularVelocity:0,style:'brown'});\n      ledge(356,136,246,{rotating:true,angle:0,angularVelocity:0,style:'grey'});\n      pickup('meal',424,0,213);break;\n    case 5:\n      trap('fire',293,72);trap('spikes',484);break;\n    case 6:\n      trap('saw',298);trap('ball',506,35);break;\n    case 7:\n      trap('spikehead',300);trap('arrow',546,25);ledge(407,103,303);break;\n    case 8:\n      trap('falling',291);ledge(410,134,255);pickup('meal',475,0,228);break;\n    case 9:\n      pickup('meal',505);pickup('task',605,2);break;\n    case 10:\n      platforms.push(fanPlatform(274,311,112));ledge(425,110,249);pickup('meal',485,0,223);break;\n  }\n  platforms.push(...ground);\n}\n\nfunction buildCourse() {\n  if(demoMode==='tour'){buildDemoCourse();return;}\n  const config=currentLevel(), width=510;\n  finishX=config.sections*width-80;\n  checkpointLine=Math.floor(config.sections/2)*width+36;\n  ground=[];platforms=[];course=[];springs=[];rocks=[];debris=[];traps=[];\n  let boost=0,treat=0;\n  const boostTypes=level>=3?['fruit','task','veg','task','meal','task','veg','task']:['fruit','task','veg','meal','fruit','task','veg','fruit'];\n  for(let i=0;i<config.sections;i++){\n    const x=i*width;\n    ground.push({x,w:i===config.sections-1?width:width-58,y:390,solid:true});\n    platforms.push({x:x+110,w:147,y:309,solid:false},\n      {x:x+260,w:135,y:241,solid:false,rotating:level>=2&&i%3!==0,angle:0,angularVelocity:0,style:i%2?'brown':'grey'});\n    if(level>0&&i%2===0) springs.push({x:x+314,y:390,activated:-100,mystery:['booster','rocket','depleter'][Math.floor(Math.random()*3)]});\n    if(level>0&&i%2===1) rocks.push({x:x+378,y:105,ground:390,vy:0,phase:'hanging',age:0,hit:false});\n    if(level>=3&&i%5===3)platforms.push(fanPlatform(x+284,310));\n    if(level>=3&&i%4===2){\n      const types=trapOrder.slice(0,level-2);\n      const type=i===2?types.at(-1):types[(i-2)/4%types.length];\n      const trap={type,x:x+415,y:390,phase:i*31,lastHit:-100};\n      traps.push(trap);\n      if(type==='falling'){\n        trap.platform={x:trap.x-42,w:84,y:315,solid:false,falling:trap,angle:0};\n        platforms.push(trap.platform);\n      }\n    }\n    const pattern=config.second&&i>=config.sections/2?config.second:config.ratio;\n    for(let slot=0;slot<pattern.length;slot++){\n      const isBoost=pattern[slot]==='B';\n      const type=isBoost?boostTypes[boost++%boostTypes.length]:'treat';\n      const variant=(isBoost?boost-1:treat++)%supplies[type].icons.length;\n      const high=slot===3&&i%2===1;\n      course.push({x:x+125+slot*76,y:high?216:365,type,variant});\n    }\n  }\n  platforms.push(...ground);\n}\n\nconst supplies = {\n  fruit:{boost:18,icons:['Apple','Orange','Bananas']}, veg:{boost:18,icons:['broccoli','carrot','tomato']},\n  meal:{boost:35,icons:['meal']}, treat:{boost:22,icons:['soda','chips','chocolate']},\n  task:{boost:12,icons:['reading','cleaning','laundry','running','lifting']}, target:{boost:25,icons:['target']}\n};\nlet player, rocket, target, items, camera, tick, checkpoint, score, state, notice, noticeUntil;\nlet taught = new Set();\nlet maze=null, escapes=0;\nlet showInstructions=true;\nfunction reset(nextState = 'ready', keepScore = false){\n  buildCourse();\n  maze=null;stage.classList.remove('maze');\n  player={x:100,y:348,w:30,h:42,vx:0,vy:0,dir:1,power:70,quick:0,crash:0,ice:0,iceTasks:0,jumps:0,support:ground[0],drop:null,launch:null};\n  rocket={x:-250,y:270,active:level>0,ride:0,rest:0,started:level>0,pullScale:1,elapsed:0,refocusDelay:0,offeredTarget:false};\n  target=null;items=course.map(item=>({...item}));\n  camera=0;tick=0;checkpoint=100;if(!keepScore)score=0;\n  notice='';noticeUntil=0;state=nextState;taught=new Set();\n  document.getElementById('level-graphic').src=assets['level'+(themeIndex()+1)];\n  document.getElementById('level-label').textContent=demoMode==='tour'?'Demo '+(demoStation+1)+' / '+demoStations.length:'Level '+(level+1)+' / '+levels.length;\n  clearControls();\n}\nfunction clearControls(){Object.keys(controls).forEach(key=>controls[key]=false);}\n\nconst powerColor = p => p<=25?'#ef4444':p<=50?'#facc15':p<=75?'#38bdf8':'#4ade80';\nconst jumpCount = p => p>=75?3:p>=50?2:1;\nconst clamp = (x,lo,hi)=>Math.max(lo,Math.min(hi,x));\nconst px = ()=>player.x+player.w/2, py = ()=>player.y+player.h/2;\nfunction say(message){notice=message;noticeUntil=tick+135;}\nfunction jump(){\n  if(state==='lost'){reset('play');return;}\n  if(state==='won'){advance();return;}\n  if(state!=='play'||rocket.ride||player.jumps>=jumpCount(player.power))return;\n  player.vy=player.power>=50?-11.8:-8.5;player.jumps++;player.support=null;sound('jump');\n}\nfunction drop(){\n  if(state!=='play'||!player.support||player.support.solid)return;\n  player.drop=player.support;player.support=null;player.vy=Math.max(2.5,player.vy);sound('drop');\n}\nfunction endRide(){\n  rocket.ride=0;rocket.active=false;rocket.rest=currentLevel().rest;target=null;\n}\nconst iceTaskGoal = () => level+1;\nfunction clearIce(){\n  player.ice=0;player.iceTasks=0;sound('refocus');\n}\nfunction collect(item){\n  const quick=item.type==='treat';\n  const gain=Math.min(supplies[item.type].boost,100-player.power);\n  player.power+=gain;\n  if(quick){\n    player.quick+=gain;player.crash+=8;\n    if(!player.ice)player.iceTasks=0;\n    player.ice=Math.min(6,player.ice+1);\n  }\n  if(item.type!=='target')rocket.pullScale=clamp(rocket.pullScale+(quick?.24:-.16),.38,2.35);\n  sound(quick?'treat':item.type==='target'?'refocus':item.type==='task'?'task':'boost');\n  if(item.type==='task'){\n    score+=10;\n    if(player.ice)player.iceTasks++;\n    if(rocket.ride)endRide();\n  }\n  if(item.type==='target')endRide();\n  const cleared=player.ice&&!quick&&(player.power>=100||player.iceTasks>=iceTaskGoal());\n  if(cleared)clearIce();\n  const label={fruit:'Steady power',veg:'Steady power',meal:'Meal power',task:'Task complete',target:'Back on track'};\n  if(cleared)say('Ice cleared \u00b7 steady footing!');\n  else if(quick)say('Quick boost \u00b7 ice \u00d7'+player.ice+' \u00b7 stronger rocket pull');\n  else say(label[item.type]+' +'+Math.round(gain));\n}\n\nfunction step(){\n  tick++;\n  if(state==='maze'){stepMaze();return;}\n  if(state!=='play')return;\n  const wasRiding=rocket.ride>0;\n  if(!demoMode&&showInstructions&&teachFirstEncounter())return;\n  if(!demoMode&&level===0&&!rocket.started&&player.x>=435)launchFirstRocket();\n  const quickDrain=Math.min(.19,player.quick), crashDrain=player.quick>0?0:Math.min(.09,player.crash);\n  player.quick-=quickDrain;player.crash-=crashDrain;\n  player.power=Math.max(0,player.power-quickDrain-crashDrain-(rocket.ride ? .18 : currentLevel().drain));\n  const ice=player.ice;\n  const speed=(player.power<=25?2.4:player.power>=50?4.8:3.8)*currentLevel().pace;\n  const direction=Number(controls.right)-Number(controls.left);\n  if(direction){player.vx+=direction*(ice ? .42/(1+ice*.42) : .82);player.dir=direction;}else player.vx*=ice ? 1-.037/(ice+1) : .72;\n  player.vx=clamp(player.vx,-speed,speed);\n  if(player.launch){\n    player.vx=(player.launch.x-px())*.25;\n    if(tick-player.launch.activated>30)player.launch=null;\n  }\n  const support=player.support;\n  updatePlatforms();\n  if(player.support===support&&(support?.rotating||support?.fan)&&!support.disabled&&!player.drop){\n    player.y=platformY(support,px())-player.h;\n  }\n  const oldBottom=player.y+player.h;\n  player.x=clamp(player.x+player.vx,12,finishX+40);\n  player.vy=rocket.ride?(controls.jump?-4.7:Math.min(4,player.vy+.24)):player.vy+.44;\n  player.y+=player.vy;\n  if(player.y<80){player.y=80;player.vy=0;}\n  player.support=null;\n  const landing=platforms.filter(p=>!p.disabled&&p!==player.drop&&player.x+player.w>p.x&&player.x<p.x+p.w&&\n    (oldBottom<=platformY(p,px())+0.5||p===support)&&player.y+player.h>=platformY(p,px())-0.5&&player.vy>=0)\n    .sort((a,b)=>platformY(a,px())-platformY(b,px()))[0];\n  if(landing){player.y=platformY(landing,px())-player.h;player.vy=0;player.jumps=0;player.support=landing;}\n  const spring=springs.find(pad=>Math.abs(px()-pad.x)<27&&oldBottom<=pad.y&&player.y+player.h>=pad.y&&player.vy>=0);\n  if(spring&&(!landing||landing.solid)&&!rocket.ride){\n    player.vy=-15.8;player.y=spring.y-player.h-1;player.jumps=0;player.support=null;\n    spring.activated=tick;player.launch=spring.mystery?spring:null;sound('spring');say('Trampoline!');\n  }\n  if(player.drop&&(player.y>player.drop.y+16||landing))player.drop=null;\n  if(player.launch?.mystery&&Math.hypot(px()-player.launch.x,py()-146)<40){\n    const pad=player.launch,result=pad.mystery;pad.mystery=null;player.launch=null;\n    if(result==='rocket'){beginRide();say('Mystery pickup \u00b7 rocket!');}\n    else {collect({type:result==='booster'?'meal':'treat'});say(result==='booster'?'Mystery pickup \u00b7 meal boost!':'Mystery pickup \u00b7 quick boost!');}\n  }\n  updateRocks();\n  updateTraps();\n  if(player.x>=checkpointLine&&checkpoint===100&&landing){checkpoint=checkpointLine;say('Checkpoint!');}\n  if(player.x>=finishX&&landing){state='won';sound('win');showResult(true);return;}\n  if(player.y>510){player.x=checkpoint;player.y=270;player.vy=0;player.jumps=0;player.drop=null;player.launch=null;player.power=Math.max(0,player.power-22);say('Try that jump again');}\n  camera+= (clamp(player.x-220,0,finishX+90-canvas.width)-camera)*.12;\n  for(let i=items.length-1;i>=0;i--){\n    const item=items[i];\n    if(Math.hypot(px()-item.x,py()-pickupY(item))<(item.type==='treat'?33:26)){collect(item);items.splice(i,1);}\n  }\n  if(rocket.ride&&!rocket.offeredTarget&&++rocket.elapsed>=rocket.refocusDelay){\n    rocket.offeredTarget=true;\n    target={type:'target',x:Math.min(finishX+35,player.x+145+level*21),y:clamp(player.y-32,120,345)};\n    say('Get back on track is available!');\n  }\n  if(target){\n    const dx=target.x-px(),dy=target.y-py(),d=Math.hypot(dx,dy);\n    if(d<27)collect(target);\n    else{\n      const pull=clamp((1/rocket.pullScale-1)*1.8-.20,-1.5,3);\n      if(pull>0||d<170){\n        const force=pull>0?pull:pull*(1-d/170);\n        target.x-=dx/d*force;target.y=clamp(target.y-dy/d*force,105,365);\n      }\n    }\n  }\n  if(rocket.ride&&!--rocket.ride)endRide();\n  if(rocket.rest&&!--rocket.rest){rocket.active=true;rocket.x=Math.min(finishX+20,player.x+205);rocket.y=235;}\n  if(rocket.active){\n    const dx=px()-rocket.x,dy=py()-rocket.y,d=Math.hypot(dx,dy);\n    if(d<29){\n      beginRide();\n    }else{const speed=Math.min(7,currentLevel().pull*rocket.pullScale*(player.power<=25?2:1));rocket.x+=dx/d*speed;rocket.y+=dy/d*speed;}\n  }\n  if(player.power<=0){\n    if(wasRiding)beginHyperfocus();\n    else{state='lost';sound('lose');showResult(false);}\n  }\n}\nconst mazeMap=[\n '###################',\n '#S....#.....#....E#',\n '#.###.#.###.#.###.#',\n '#...#.#...#.#...#.#',\n '###.#.#.#.#.###.#.#',\n '#b..#.B.#...G...#.#',\n '#.###.#.#.#.#.#.#.#',\n '#.....#g..#.#.#...#',\n '#.^...#...#.#..^..#',\n '#.....#.....#.....#',\n '###################'\n];\nconst mazeTraps=[{x:4,y:1,phase:5},{x:9,y:7,phase:33},{x:14,y:5,phase:58},{x:17,y:3,phase:81}];\nconst cellSize=30, mazeLeft=115, mazeTop=92;\nfunction beginHyperfocus(){\n  maze={x:1,y:1,blue:false,gold:false,age:0,nextMove:0,dir:1};\n  state='maze-intro';stage.classList.add('maze');sound('rocket');\n  showLesson('Hyperfocus room',['Find your way back',\n    'Find the blue and gold switches to open their doors. Move with the arrows or touch buttons, and wait for the spikes to go down before crossing. One hit ends the run. Reach the exit to continue your level.',['target']],\n    'Enter maze',()=>{lesson.hidden=true;clearControls();state='maze';canvas.focus();});\n}\nfunction mazeTrapActive(trap){return (maze.age+trap.phase)%106>=60;}\nfunction stepMaze(){\n  maze.age++;\n  if(maze.age>=maze.nextMove){\n    const dx=Number(controls.right)-Number(controls.left);\n    const dy=Number(controls.drop)-Number(controls.jump);\n    if(dx||dy){\n      const x=maze.x+dx,y=maze.y+(dx?0:dy);\n      const tile=mazeMap[y]?.[x];\n      if(tile&&tile!=='#'&&(tile!=='B'||maze.blue)&&(tile!=='G'||maze.gold)){\n        maze.x=x;maze.y=y;maze.nextMove=maze.age+7;\n        if(dx)maze.dir=dx;\n        if(tile==='b'&&!maze.blue){maze.blue=true;sound('task');}\n        if(tile==='g'&&!maze.gold){maze.gold=true;sound('task');}\n        if(tile==='E'&&maze.blue&&maze.gold){escapeMaze();return;}\n      }\n    }\n  }\n  if(mazeTraps.some(trap=>trap.x===maze.x&&trap.y===maze.y&&mazeTrapActive(trap))){\n    state='lost';stage.classList.remove('maze');sound('lose');\n    showResult(false,'A maze trap ended this run. Retry to restart the current level from its beginning.');\n  }\n}\nfunction escapeMaze(){\n  escapes++;maze=null;stage.classList.remove('maze');\n  if(demoMaze()){state='won';sound('win');showResult(true);return;}\n  endRide();player.power=50;player.quick=0;player.crash=0;\n  player.vx=0;player.vy=0;\n  if(player.y+player.h>435){player.x=checkpoint;player.y=280;player.support=null;player.drop=null;player.jumps=0;}\n  clearControls();state='play';sound('refocus');say('Maze escaped \u00b7 back on track!');\n}\nfunction drawMaze(){\n  ctx.fillStyle='#101830';ctx.fillRect(0,0,800,460);\n  ctx.font='bold 24px system-ui';ctx.textAlign='left';ctx.fillStyle='#e8f4ff';\n  ctx.fillText('HYPERFOCUS ROOM',mazeLeft,36);\n  ctx.font='bold 13px system-ui';\n  ctx.fillStyle=maze.blue?'#67e8f9':'#b4c2d9';ctx.fillText((maze.blue?'\u2713 ':'\u25cb ')+'BLUE SWITCH',mazeLeft,64);\n  ctx.fillStyle=maze.gold?'#fde68a':'#b4c2d9';ctx.fillText((maze.gold?'\u2713 ':'\u25cb ')+'GOLD SWITCH',mazeLeft+142,64);\n  ctx.fillStyle='#b4c2d9';ctx.fillText('ARROWS TO MOVE  \u00b7  WATCH THE SPIKES',mazeLeft+285,64);\n  for(let row=0;row<mazeMap.length;row++)for(let col=0;col<mazeMap[row].length;col++){\n    const tile=mazeMap[row][col],x=mazeLeft+col*cellSize,y=mazeTop+row*cellSize;\n    ctx.fillStyle=tile==='#'?'#344568':(col+row)%2?'#1b2a47':'#213253';\n    ctx.fillRect(x,y,cellSize-1,cellSize-1);\n    if(tile==='#'){ctx.fillStyle='#486287';ctx.fillRect(x+2,y+2,cellSize-5,4);}\n    if(tile==='B'||tile==='G'){\n      const blue=tile==='B',open=blue?maze.blue:maze.gold;\n      ctx.fillStyle=blue?'#38bdf8':'#fbbf24';\n      if(open)ctx.fillRect(x+4,y+23,22,3);\n      else for(let bar=5;bar<26;bar+=7)ctx.fillRect(x+bar,y+3,3,23);\n    }\n    if(tile==='b'||tile==='g'){\n      const blue=tile==='b',on=blue?maze.blue:maze.gold;\n      ctx.fillStyle=on?'#d1fae5':blue?'#38bdf8':'#fbbf24';\n      ctx.beginPath();ctx.arc(x+15,y+15,on?5:9,0,Math.PI*2);ctx.fill();\n    }\n    if(tile==='E'){\n      ctx.fillStyle=maze.blue&&maze.gold?'#4ade80':'#94a3b8';\n      ctx.fillRect(x+5,y+4,20,23);ctx.fillStyle='#101830';ctx.fillRect(x+8,y+7,14,18);\n      ctx.fillStyle='#fff';ctx.font='bold 13px system-ui';ctx.fillText('\u2197',x+9,y+20);\n    }\n  }\n  for(const trap of mazeTraps){\n    const x=mazeLeft+trap.x*cellSize,y=mazeTop+trap.y*cellSize;\n    const active=mazeTrapActive(trap);\n    ctx.fillStyle=active?'#8a2942':(maze.age+trap.phase)%106>=45?'#ae7327':'#465471';\n    ctx.fillRect(x+2,y+2,26,26);\n    if(active)sprite('spikes',x+3,y+4,24,16);\n    else{ctx.fillStyle='#d4d8e8';ctx.fillRect(x+4,y+22,22,3);}\n  }\n  ctx.save();ctx.translate(mazeLeft+maze.x*cellSize+15,mazeTop+maze.y*cellSize+17);ctx.scale(maze.dir,1);\n  sprite(character+'Idle',-17,-17,34,32,true);ctx.restore();\n}\n\nfunction beginRide(){\n  rocket.active=false;rocket.rest=0;rocket.elapsed=0;rocket.offeredTarget=false;\n  rocket.refocusDelay=demoMode==='tour'?60:105+level*36;\n  rocket.ride=rocket.refocusDelay+360+level*12;\n  target=null;sound('rocket');say('Side quest! Get back on track appears later');\n}\n\nfunction updatePlatforms(){\n  for(const p of platforms){\n    if(p.rotating){\n      const riding=player.support===p;\n      const weight=riding?clamp((px()-p.x-p.w/2)/(p.w/2),-1,1):0;\n      const torque=Math.abs(weight)>.20?weight*.037:0;\n      p.angularVelocity=(p.angularVelocity+torque-p.angle*.025)*.89;\n      p.angle=clamp(p.angle+p.angularVelocity,-.77,.77);\n      if(riding&&Math.abs(p.angle)>.49&&weight*p.angle>0){\n        dumpRider(p,Math.sign(p.angle),5,3);\n        say('Platform tipped!');\n      }\n    }\n    if(p.fan)updateFan(p);\n    if(p.falling){\n      if(player.support===p&&p.fallAt===undefined)p.fallAt=tick+35;\n      if(tick>=p.fallAt){p.y+=5+Math.min(10,(tick-p.fallAt)*.14);p.disabled=true;}\n    }\n  }\n}\nfunction dumpRider(platform,direction,horizontal,vertical){\n  player.support=null;player.drop=platform;\n  player.x=direction>0?platform.x+platform.w+2:platform.x-player.w-2;\n  player.vx=direction*horizontal;player.vy=vertical;\n}\nfunction updateFan(p){\n  const riding=player.support===p;\n  if(p.phase==='idle'&&riding){p.phase='up';say('Fan lift \u00b7 watch the ceiling!');}\n  if(p.phase==='up'){\n    p.y=Math.max(p.topY,p.y-.76);\n    if(riding&&p.y-player.h<=p.spikeY+3){\n      player.power=Math.max(0,player.power-18);\n      dumpRider(p,px()<p.x+p.w/2?-1:1,4,2);\n      sound('hit');say('Ceiling spikes \u00b7 \u221218 dopamine');\n    }\n    if(p.y===p.topY){p.phase='wait';p.returnAt=tick+55;}\n  }else if(p.phase==='wait'&&tick>=p.returnAt)p.phase='down';\n  else if(p.phase==='down'){\n    p.y=Math.min(p.baseY,p.y+1.15);\n    if(p.y===p.baseY)p.phase='idle';\n  }\n}\nfunction trapPose(trap){\n  const phase=tick+trap.phase;\n  if(trap.type==='saw')return {x:trap.x+Math.sin(phase/32)*44,y:350,size:50,frame:38,active:true};\n  if(trap.type==='ball')return {x:trap.x+Math.sin(phase/37)*73,y:329-Math.abs(Math.sin(phase/37))*40,size:48,frame:28,active:true};\n  if(trap.type==='spikehead')return {x:trap.x,y:350-Math.max(0,Math.sin(phase/40))*140,size:57,frame:54,active:true};\n  if(trap.type==='arrow')return {x:trap.x+76-(phase%135)*1.5,y:335,size:33,frame:18,active:true};\n  if(trap.type==='fire')return {x:trap.x,y:367,size:50,frame:16,height:32,active:phase%150<78};\n  return {x:trap.x,y:375,size:35,frame:16,active:true};\n}\nfunction updateTraps(){\n  for(const trap of traps){\n    if(trap.type==='falling'||Math.abs(trap.x-px())>240||tick-trap.lastHit<75)continue;\n    const pose=trapPose(trap);\n    if(pose.active&&Math.abs(px()-pose.x)<22&&Math.abs(py()-pose.y)<30){\n      trap.lastHit=tick;player.power=Math.max(0,player.power-10);player.vy=-4;\n      sound('hit');say(trapTitles[trap.type]+' \u00b7 \u221210 power');\n    }\n  }\n}\nfunction pickupY(item){\n  const t=tick/13+item.x/85;\n  return item.y-Math.abs(Math.sin(t))*(item.type==='treat'?23:6);\n}\nfunction updateRocks(){\n  for(const rock of rocks){\n    if(rock.phase==='hanging'&&Math.abs(px()-rock.x)<141){rock.phase='shake';rock.age=0;}\n    if(rock.phase==='shake'&&++rock.age>=28){rock.phase='fall';rock.vy=0;}\n    if(rock.phase!=='fall')continue;\n    rock.vy+=.68;rock.y=Math.min(rock.ground,rock.y+rock.vy);\n    if(!rock.hit&&Math.abs(px()-rock.x)<33&&player.y+player.h>rock.y-62&&player.y<rock.y){\n      player.power=Math.max(0,player.power-12);player.vx=px()<rock.x?-4:4;\n      rock.hit=true;sound('hit');say('Rockhead \u00b7 \u221212 power');\n    }\n    if(rock.y>=rock.ground){\n      rock.phase='landed';rock.y=rock.ground+12;rock.age=tick;sound('impact');\n      for(let i=0;i<26;i++)debris.push({x:rock.x+(Math.random()-.5)*35,y:rock.ground-5,\n        vx:(Math.random()-.5)*8,vy:-1.5-Math.random()*6,life:20+Math.random()*23,\n        color:['#6ba322','#9dc64a','#41751e','#bb8449'][i%4],size:2+i%4});\n    }\n  }\n  for(let i=debris.length-1;i>=0;i--){\n    const bit=debris[i];bit.x+=bit.vx;bit.y+=bit.vy;bit.vy+=.35;\n    if(--bit.life<=0||bit.y>395)debris.splice(i,1);\n  }\n}\nlet audio, soundEnabled=true;\nconst notes={\n jump:[400,740,.13,'square'],drop:[290,130,.12,'triangle'],boost:[500,950,.17,'sine'],\n treat:[880,420,.19,'square'],task:[660,1100,.19,'triangle'],refocus:[440,1000,.24,'sine'],\n rocket:[145,570,.28,'sawtooth'],spring:[200,760,.24,'triangle'],\n impact:[110,38,.25,'triangle'],hit:[210,74,.20,'square'],\n win:[540,1200,.32,'triangle'],lose:[340,110,.32,'triangle']\n};\nfunction sound(name){\n  if(!soundEnabled||!audio||audio.state!=='running')return;\n  const [from,to,duration,shape]=notes[name], time=audio.currentTime;\n  const wave=audio.createOscillator(), volume=audio.createGain();\n  wave.type=shape;wave.frequency.setValueAtTime(from,time);wave.frequency.exponentialRampToValueAtTime(to,time+duration);\n  volume.gain.setValueAtTime(.0001,time);volume.gain.exponentialRampToValueAtTime(.09,time+.018);\n  volume.gain.exponentialRampToValueAtTime(.0001,time+duration);\n  wave.connect(volume).connect(audio.destination);wave.start(time);wave.stop(time+duration);\n}\nfunction unlockSound(){\n  const Audio=window.AudioContext||window.webkitAudioContext;\n  if(!Audio)return;\n  try{audio??=new Audio();if(audio.state==='suspended')audio.resume().catch(()=>{});}catch{}\n}\n\nlet musicEnabled=true,musicNext=0,musicIndex=0,musicBus;\nconst melody=[60,64,67,72,67,64,62,65,69,74,69,65,64,67,71,76,71,67,62,65,69,74,67,64];\nfunction musicLoop(){\n  if(!audio||audio.state!=='running')return;\n  const active=musicEnabled&&['play','maze'].includes(state);\n  if(!musicBus){musicBus=audio.createGain();musicBus.gain.value=0;musicBus.connect(audio.destination);}\n  musicBus.gain.value=active?.55:0;\n  if(!active){musicNext=0;return;}\n  const now=audio.currentTime;\n  if(musicNext<now)musicNext=now+.025;\n  const beat=state==='maze'?.23:.28;\n  while(musicNext<now+.10){\n    const note=melody[musicIndex++%melody.length]-(state==='maze'?5:0);\n    const wave=audio.createOscillator(),envelope=audio.createGain();\n    wave.type='triangle';wave.frequency.value=440*2**((note-69)/12);\n    envelope.gain.setValueAtTime(.0001,musicNext);\n    envelope.gain.exponentialRampToValueAtTime(.035,musicNext+.024);\n    envelope.gain.exponentialRampToValueAtTime(.0001,musicNext+beat*.9);\n    wave.connect(envelope).connect(musicBus);wave.start(musicNext);wave.stop(musicNext+beat);\n    musicNext+=beat;\n  }\n}\n\nfunction sprite(key,x,y,size,frameSize,animate=false,age=tick,frameHeight=frameSize){\n  const image=sprites[key];if(!image?.complete||!image.naturalWidth)return false;\n  const frame=animate?Math.floor(age/3)%(image.naturalWidth/frameSize):0;\n  ctx.drawImage(image,frame*frameSize,0,frameSize,frameHeight,Math.round(x),Math.round(y),size,size);return true;\n}\nfunction terrain(p){\n  if(p.fan){\n    const art=sprites[p.phase==='idle'?'fanIdle':'fanMotion'];\n    if(art.complete&&art.naturalWidth){\n      const frame=Math.floor(tick/3)%(art.naturalWidth/24);\n      ctx.drawImage(art,frame*24,0,24,8,p.x,p.y,p.w,24);\n    }\n    const spikes=sprites.spikes;\n    ctx.save();ctx.translate(p.x,p.spikeY);ctx.scale(1,-1);\n    ctx.fillStyle='#53617c';ctx.fillRect(0,13,p.w,6);\n    if(spikes.complete&&spikes.naturalWidth){\n      for(let x=0;x<p.w;x+=16)ctx.drawImage(spikes,x,0,Math.min(16,p.w-x),16);\n    }\n    ctx.restore();\n    return;\n  }\n  if(p.falling){\n    if(p.y<475){\n      const art=sprites.falling;\n      if(art.complete&&art.naturalWidth)ctx.drawImage(art,Math.floor(tick/5)%(art.naturalWidth/32)*32,0,32,10,p.x,p.y,p.w,16);\n    }\n    return;\n  }\n  if(p.rotating){\n    ctx.save();ctx.translate(p.x+p.w/2,p.y);ctx.rotate(p.angle);\n    const art=sprites[p.style];\n    if(art.complete&&art.naturalWidth)ctx.drawImage(art,-p.w/2,-1,p.w,18);\n    ctx.restore();return;\n  }\n  const [tileX,tileY,color]=themes[themeIndex()];\n  ctx.fillStyle=p.solid?color:'#9a644a';\n  ctx.fillRect(p.x,p.y,p.w,p.solid?70:16);\n  const atlas=sprites.terrain;if(!atlas.complete||!atlas.naturalWidth)return;\n  for(let offset=Math.max(0,Math.floor((camera-p.x)/32)*32);offset<Math.min(p.w,camera+canvas.width-p.x);offset+=32){\n    const w=Math.min(32,p.w-offset);\n    for(let row=0;row<(p.solid?70:16);row+=32){\n      const h=Math.min(32,(p.solid?70:16)-row);\n      ctx.drawImage(atlas,tileX,tileY+(row?16:0),w/2,h/2,p.x+offset,p.y+row,w,h);\n    }\n  }\n}\nfunction drawPlayer(){\n  const pose=player.support?(Math.abs(player.vx)>.2?'Run':'Idle'):player.vy>=0?'Fall':player.jumps>1?'Double Jump':'Jump';\n  const glow=powerColor(player.power);\n  ctx.save();ctx.translate(Math.round(px()),Math.round(player.y+player.h));ctx.scale(player.dir,1);\n  ctx.shadowColor=glow;ctx.shadowBlur=19;ctx.fillStyle=glow+'55';ctx.beginPath();ctx.ellipse(0,-22,24,28,0,0,2*Math.PI);ctx.fill();\n  if(!sprite(character+pose,-36,-65,72,32,true)){ctx.fillStyle='#172554';ctx.fillRect(-14,-41,28,41);}\n  ctx.restore();\n  if(rocket.ride)sprite('rocketMotion',px()-34,py(),38,80,true);\n}\nfunction render(){\n  ctx.imageSmoothingEnabled=false;\n  if(state==='maze'||state==='maze-intro'){drawMaze();return;}ctx.fillStyle='#86bbef';ctx.fillRect(0,0,800,460);\n  for(let x=-Math.floor(camera*.22)%128;x<800;x+=128)for(let y=0;y<460;y+=128)sprite('sky'+themeIndex(),x,y,128,64);\n  ctx.save();ctx.translate(-Math.round(camera),0);\n  for(const p of platforms)if(p.x+p.w>=camera&&p.x<camera+800)terrain(p);\n  sprite('startMotion',27,319,76,64,true);\n  sprite('checkpoint',checkpointLine-38,319,76,64,true);\n  sprite('finishMotion',finishX-32,319,76,64,true);\n  for(const pad of springs){\n    if(pad.x<camera-50||pad.x>camera+850)continue;\n    if(pad.mystery){\n      const bob=Math.sin(tick/9+pad.x)*5;\n      ctx.fillStyle='#412c71';ctx.strokeStyle='#fde68a';ctx.lineWidth=3;\n      ctx.beginPath();ctx.arc(pad.x,146+bob,17,0,Math.PI*2);ctx.fill();ctx.stroke();\n      ctx.font='bold 22px system-ui';ctx.textAlign='center';ctx.fillStyle='#fff';\n      ctx.fillText('?',pad.x,154+bob);\n    }\n    const age=tick-pad.activated;\n    sprite(age<24?'springJump':'springIdleMotion',pad.x-27,pad.y-49,54,age<24?28:80,true,age<24?age:tick);\n  }\n  for(const rock of rocks){\n    if(rock.x<camera-70||rock.x>camera+870)continue;\n    const shaking=rock.phase==='shake', hit=rock.phase==='landed'&&tick-rock.age<12;\n    const offset=shaking?Math.sin(rock.age*1.7)*(1+rock.age/15):0;\n    if(rock.phase==='hanging'||shaking){\n      ctx.strokeStyle='#596477';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(rock.x,0);ctx.lineTo(rock.x+offset,rock.y-43);ctx.stroke();\n    }\n    ctx.save();\n    ctx.beginPath();ctx.rect(rock.x-48,0,96,rock.ground);ctx.clip();\n    sprite(hit?'rockHit':rock.phase==='fall'?'rockIdle':'rockBlink',rock.x+offset-32,rock.y-62,64,42,true,hit?tick-rock.age:tick);\n    ctx.restore();\n  }\n  for(const trap of traps){\n    if(trap.type==='falling'||trap.x<camera-130||trap.x>camera+930)continue;\n    const pose=trapPose(trap);\n    const key=trap.type==='fire'&&!pose.active?'fireOff':trap.type;\n    if(trap.type==='ball'){\n      ctx.strokeStyle='#606b7a';ctx.lineWidth=2;ctx.beginPath();\n      ctx.moveTo(trap.x,pose.y-82);ctx.lineTo(pose.x,pose.y);ctx.stroke();\n    }\n    const art=sprites[key];\n    if(art.complete&&art.naturalWidth){\n      const width=trap.type==='ball'||trap.type==='spikes'?art.naturalWidth:pose.frame;\n      const height=pose.height||art.naturalHeight;\n      sprite(key,pose.x-pose.size/2,pose.y-pose.size/2,pose.size,width,true,tick,height);\n    }\n  }\n  for(const bit of debris){ctx.fillStyle=bit.color;ctx.fillRect(bit.x,bit.y,bit.size,bit.size);}\n\n  for(const item of items){\n    if(item.x<camera-30||item.x>camera+830)continue;\n    const fruit=item.type==='fruit',key=supplies[item.type].icons[item.variant];\n    const size=item.type==='treat'?50:43;\n    if(item.type==='treat'){\n      ctx.fillStyle='#fff4aeaa';ctx.beginPath();\n      ctx.ellipse(item.x,pickupY(item),17+Math.sin(tick/7)*3,17,0,0,Math.PI*2);ctx.fill();\n    }\n    sprite(fruit?key:key+'Motion',item.x-size/2,pickupY(item)-size/2,size,fruit?32:80,true);\n  }\n  if(rocket.active)sprite('rocketMotion',rocket.x-24,rocket.y-24+Math.sin(tick/7)*2,48,80,true);\n  if(target){\n    sprite('targetMotion',target.x-24,target.y-24,48,80,true);\n    ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillStyle='#132642';ctx.fillText('GET BACK ON TRACK',target.x,target.y-29);\n  }\n  drawPlayer();ctx.restore();\n  ctx.fillStyle='#152642';ctx.fillRect(14,12,270,player.ice?108:90);\n  ctx.textAlign='left';ctx.font='bold 14px system-ui';ctx.fillStyle='#fff';\n  ctx.fillText('DOPAMINE  '+Math.ceil(player.power)+'%',25,33);\n  ctx.fillStyle='#435679';ctx.fillRect(25,43,190,12);ctx.fillStyle=powerColor(player.power);ctx.fillRect(25,43,190*player.power/100,12);\n  ctx.font='bold 12px system-ui';ctx.fillText(['','SINGLE JUMP','DOUBLE JUMP','TRIPLE JUMP'][jumpCount(player.power)]+(player.ice?' \u00b7 ICE \u00d7'+player.ice:rocket.ride?' \u00b7 ROCKET RIDE':''),25,73);\n  ctx.fillStyle='#e2e8f0';ctx.fillText('ROCKET GRAVITY  \u00d7'+rocket.pullScale.toFixed(2),25,91);\n  if(player.ice)ctx.fillText('CLEAR ICE: 100% POWER OR '+player.iceTasks+'/'+iceTaskGoal()+' TASKS',25,109);\n  ctx.fillStyle='#152642';ctx.fillRect(675,12,110,35);ctx.fillStyle='#fff';ctx.fillText('TASKS  '+score/10,691,35);\n  if(tick<noticeUntil){ctx.textAlign='center';ctx.fillStyle='#152642';ctx.fillRect(207,96,386,29);ctx.fillStyle='#fff';ctx.fillText(notice,400,115);}\n\n}\nconst codes={ArrowLeft:'left',KeyA:'left',ArrowRight:'right',KeyD:'right',ArrowDown:'drop',KeyS:'drop',ArrowUp:'jump',KeyW:'jump',Space:'jump'};\nfunction press(key){\n  if(state==='maze'&&!controls[key])maze.nextMove=0;\n  if(state==='play'&&!controls[key]){if(key==='jump')jump();if(key==='drop')drop();}\n  controls[key]=true;\n}\naddEventListener('keydown',event=>{\n  if(event.target.closest?.('button,a,select,input')||!['play','maze'].includes(state)||!codes[event.code])return;\n  event.preventDefault();press(codes[event.code]);\n});\naddEventListener('keyup',event=>{if(codes[event.code])controls[codes[event.code]]=false;});\naddEventListener('blur',()=>Object.keys(controls).forEach(key=>controls[key]=false));\nfor(const button of document.querySelectorAll('[data-control]')){\n  const key=button.dataset.control;\n  button.onpointerdown=event=>{event.preventDefault();button.setPointerCapture(event.pointerId);press(key);};\n  button.onpointerup=button.onpointercancel=button.onlostpointercapture=()=>controls[key]=false;\n}\nconst stage = document.getElementById('stage');\nlet nativeFullscreen = false;\nconst stageTools = document.getElementById('stage-tools');\nconst lesson = document.getElementById('lesson');\nconst nextButton = document.getElementById('lesson-next');\nconst skipButton = document.getElementById('lesson-skip');\nconst roster = document.getElementById('roster');\nconst intro = [\n  ['Boost your power','Meals give the biggest boost. Fruit and veggies give power that lasts and weaken the rocket\u2019s pull. Completing a task also gives a boost. Dopamine is a brain messenger that helps us learn what we might do again. This meter is a game rule.',['meal','carrot','reading']],\n  ['Watch for quick boosts','Soda, chips, and chocolate give quick game power. It burns away fast, costs a little extra afterward, and makes steering slippery. Each one adds more ice. Reach 100% with a steady boost or complete the task goal to clear it. These items also make the rocket\u2019s pull stronger.',['soda','chips','chocolate']],\n  ['Watch the side-quest rocket','It follows you and pulls harder when power is low. If it catches you, hold Jump to fly. Catch the moving target or finish a task to get back on track.',['rocket','target']]\n];\nconst fieldLessons = {\n  fruit:['Fruit and veggies','These give +18 steady power and weaken the rocket\u2019s pull.',['Apple','carrot']],\n  meal:['Meal boost','Meals give +35, the biggest power boost. They weaken the rocket\u2019s pull, too.',['meal']],\n  task:['Complete a task','Tasks give +12 power and can clear ice. If you\u2019re on a rocket ride, completing a task ends the ride.',['reading']],\n  treat:['Quick boost','This gives up to +22 at first, then drains quickly. Each one makes steering more slippery and rocket gravity stronger. Reach 100% with a steady boost or finish the task goal to clear the ice.',['soda']],\n  rocket:['Side-quest rocket','The rocket is coming from ahead. If it catches you, hold Jump to fly and look for a task or the moving target.',['rocket']],\n  spring:['Trampoline','Bounce up to the mystery pickup. It might be a meal boost, a quick boost, or a rocket ride.',['springIdle']],\n  rock:['Rockhead','When Rockhead starts to shake, get out of the way. It will drop and take power if it hits you.',['rockIdle']],\n  target:['Get back on track','Boosters draw this target closer. Quick boosts make it move away. Catch it for +25 and end the rocket ride.',['target']]\n};\n\nfunction showLesson(kicker, data, label, onNext, canSkip=false){\n  clearControls();\n  const [title,message,art]=data;\n  document.getElementById('lesson-kicker').textContent=kicker;\n  document.getElementById('lesson-title').textContent=title;\n  document.getElementById('lesson-text').textContent=message;\n  const artBox=document.getElementById('lesson-art');\n  artBox.replaceChildren();\n  for(const key of art){\n    const image=document.createElement('img');image.src=assets[key==='Apple'?'carrot':key];image.alt='';artBox.append(image);\n  }\n  nextButton.textContent=label;nextButton.onclick=onNext;\n  skipButton.textContent='Skip intro';skipButton.onclick=resumePlay;\n  skipButton.hidden=!canSkip;lesson.hidden=false;nextButton.focus();\n}\nfunction resumePlay(){\n  lesson.hidden=true;clearControls();state='play';canvas.focus();\n}\nfunction showIntro(index){\n  state='intro';\n  showLesson('Flight briefing \u00b7 '+(index+1)+' / '+intro.length,intro[index],\n    index===intro.length-1?'Start Level 1':'Next',\n    index===intro.length-1?resumePlay:()=>showIntro(index+1),true);\n}\nskipButton.onclick=resumePlay;\n\nfunction launchFirstRocket(){\n  rocket.started=true;rocket.active=true;rocket.x=player.x+176;rocket.y=275;\n}\nfunction teachFirstEncounter(){\n  let category;\n  if(level===1){\n    if(!taught.has('spring')&&springs.some(pad=>Math.abs(px()-pad.x)<140))category='spring';\n    else if(!taught.has('rock')&&rocks.some(rock=>Math.abs(px()-rock.x)<170))category='rock';\n  }else if(level===2&&!taught.has('rotate')&&platforms.some(p=>p.rotating&&Math.abs(px()-p.x-p.w/2)<155)){\n    taught.add('rotate');state='lesson';\n    showLesson('Level 3 \u00b7 New platform',['Rotating platforms','Stand near the middle to balance. Stay near an edge too long and the platform will tip and dump you off.',['brown','grey']],'Keep going',resumePlay);\n    return true;\n  }else if(level>=3&&!taught.has('trap')&&traps[0]&&Math.abs(px()-traps[0].x)<180){\n    taught.add('trap');state='lesson';\n    showLesson('Level '+(level+1)+' \u00b7 New trap',[trapTitles[traps[0].type],'Watch how it moves before you cross.',['target']],'Keep going',resumePlay);\n    return true;\n  }else if(level===0){\n    if(!rocket.started&&player.x>=435){launchFirstRocket();category='rocket';}\n    else if(target&&!taught.has('target'))category='target';\n    else{\n      const item=items.find(item=>Math.hypot(px()-item.x,py()-pickupY(item))<74&&\n        !taught.has(item.type==='veg'?'fruit':item.type));\n      if(item)category=item.type==='veg'?'fruit':item.type;\n    }\n  }\n  if(!category&&level>=3&&!taught.has('fan')&&platforms.some(p=>p.fan&&Math.abs(px()-p.x-p.w/2)<140)){\n    taught.add('fan');state='lesson';\n    showLesson('Level '+(level+1)+' \u00b7 Fan platform',['Rising fan','Stand on the fan to ride it up. Get off before it carries you into the ceiling spikes.',['fanIdle']],'Keep going',resumePlay);\n    return true;\n  }\n  if(!category&&target&&!taught.has('target'))category='target';\n  if(!category||taught.has(category))return false;\n  taught.add(category);state='lesson';\n  showLesson('Level '+(level+1)+' \u00b7 First encounter',fieldLessons[category],'Keep going',resumePlay);\n  return true;\n}\nfunction advance(){\n  if(!SQ_PAID){sqUpgrade();return;}\n  if(level<levels.length-1){level++;reset('play',true);}else{level=0;reset('play');}\n  resumePlay();\n}\nfunction retryCurrent(){\n  reset('play',true);\n  if(demoMode==='tour')loadDemoStation(demoStation);\n  else resumePlay();\n}\nfunction showResult(won,failureMessage){\n  if(!won)sqDeaths++;\n  if(!SQ_PAID){state='result';showLesson('Level 1 trial',[won?'Level 1 complete!':'Run over',won?'Ready for more? Unlock all 10 levels with a paid account.':'Try level 1 again, or unlock the full game.',['target']],'Unlock More Levels',sqUpgrade);skipButton.hidden=false;skipButton.textContent='Replay Level 1';skipButton.onclick=retryCurrent;return;}\n\n  const final=level===levels.length-1||demoMaze();\n  if(demoMode==='tour'&&won&&!demoMaze()){\n    showLesson('Demo Mode',[demoStations[demoStation].name+' complete!',\n      'Try the next feature, or pick any feature from the practice menu.',['target']],\n      'Next feature',nextDemo);\n    skipButton.hidden=false;skipButton.textContent='Exit to scorecard';skipButton.onclick=()=>exitStage(true);\n    return;\n  }\n  const title=won?(demoMode?'Demo complete!':final?'All '+levels.length+' levels complete!':'Level '+(level+1)+' complete!'):'Run over';\n  const message=won?(demoMaze()?'You opened both doors and escaped.':final?'Tasks completed: '+score/10+'.':'Next up: a longer course and more rocket pressure.'):\n    failureMessage||'Look for meals and steady boosts, and jump over quick boosts when you can.';\n  showLesson('Run report',[title,message,won?['target']:['meal']],\n    won?(final?'Scorecard & reflection':'Start Level '+(level+2)):(demoMode?'Retry demo':'Retry level'),\n    won?(final?()=>exitStage(true):advance):retryCurrent);\n  if(!won){\n    skipButton.hidden=false;skipButton.textContent='Exit to scorecard';skipButton.onclick=()=>exitStage(true);\n  }else if(demoMaze()){\n    skipButton.hidden=false;skipButton.textContent='Back to tour';skipButton.onclick=()=>loadDemoStation(0);\n  }\n}\nconst questions=[\n {title:'What is dopamine?',options:['A messenger in the brain','A kind of food','A timer that tells you when to stop']},\n {title:'What are side quests?',options:['The steps you planned to finish','Things that catch your attention while you\u2019re working on something else','Only things you do outside']},\n {title:'What is hyperfocus?',options:['Doing many unrelated tasks at once','Taking a short break between tasks','Getting so absorbed that switching tasks can be hard']},\n {title:'What things do you enjoy that boost your dopamine?',personal:true,options:['Music or dancing','Sports or outdoor play','Making things','Playing with friends','Games or puzzles']},\n {title:'What side quests tempt you?',personal:true,options:['Videos or notifications','A game','A new idea','Talking to someone','Looking for a snack']},\n {title:'What do you get hyperfocused on?',personal:true,options:['Games or puzzles','Reading or stories','Drawing, building, or crafting','A favorite topic','Sports or music','I\u2019m still figuring that out']}\n];\nconst report=document.getElementById('report');\nconst fields=questions.map((question,index)=>{\n  const group=document.createElement('fieldset'),title=document.createElement('legend');\n  title.textContent=question.title;group.append(title);\n  const values=question.personal?[...question.options,'Other']:question.options;\n  const inputs=values.map(value=>{\n    const label=document.createElement('label'),input=document.createElement('input');\n    label.className='choice';input.type=question.personal?'checkbox':'radio';input.name='reflection-'+index;input.value=value;\n    label.append(input,document.createTextNode(value));group.append(label);\n    return input;\n  });\n  let other;\n  if(question.personal){\n    other=document.createElement('input');other.type='text';other.placeholder='Write your own answer';\n    other.setAttribute('aria-label','Other answer for: '+question.title);\n    other.hidden=true;other.disabled=true;group.append(other);\n    inputs.at(-1).onchange=event=>{\n      other.hidden=!event.currentTarget.checked;other.disabled=other.hidden;\n      if(!other.hidden)other.focus();\n    };\n    other.onkeydown=event=>{if(event.key==='Enter')event.preventDefault();};\n  }\n  document.getElementById('reflection').append(group);\n  return {inputs,other};\n});\nfunction resetAnswers(){\n  for(const {inputs,other} of fields){\n    inputs.forEach(input=>input.checked=false);\n    if(other){other.value='';other.hidden=true;other.disabled=true;}\n  }\n}\nfunction openReport(stats){\n  sqSend();\n  document.getElementById('report-stats').textContent=stats;\n  if(!report.open)report.showModal();\n}\ndocument.getElementById('print-score').onclick=()=>{\n  document.getElementById('print-stats').textContent=document.getElementById('report-stats').textContent;\n  const printReflection=document.getElementById('print-reflection');\n  printReflection.replaceChildren();\n  questions.forEach((question,i)=>{\n    const block=document.createElement('div'),title=document.createElement('strong'),answer=document.createElement('div');\n    block.className='print-question';title.textContent=question.title;answer.className='print-answer';\n    const {inputs,other}=fields[i];\n    const selected=inputs.filter(input=>input.checked).map(input=>input.value==='Other'&&other.value.trim()?'Other: '+other.value.trim():input.value);\n    if(selected.length){\n      answer.textContent=selected.join(' \u00b7 ');answer.classList.add('print-option');\n    }else{\n      answer.textContent=inputs.map(input=>'\u25a1 '+(input.value==='Other'?'Other __________':input.value)).join('   ');\n    }\n    block.append(title,answer);printReflection.append(block);\n  });\n  window.print();\n};\n\nconst demoToolbar=document.getElementById('demo-toolbar');\nconst demoSelect=document.getElementById('demo-station');\nfor(const [index,station] of demoStations.entries()){\n  const option=document.createElement('option');\n  option.value=String(index);option.textContent=station.name;demoSelect.append(option);\n}\nfunction loadDemoStation(index){\n  if(!SQ_PAID){sqUpgrade();return;}\n  demoStation=clamp(index,0,mazeStation);\n  demoSelect.value=String(demoStation);\n  document.getElementById('demo-power-control').hidden=demoStation!==1;\n  document.getElementById('demo-power').value='85';\n  document.getElementById('demo-note').textContent=demoStations[demoStation].hint;\n  reset('play',true);\n  if(demoMaze()){beginHyperfocus();return;}\n  if(demoStation===1)player.power=85;\n  if(demoStation===9){\n    rocket.started=true;rocket.active=true;rocket.x=318;rocket.y=332;rocket.pullScale=.78;\n  }\n  resumePlay();\n}\nfunction nextDemo(){loadDemoStation((demoStation+1)%demoStations.length);}\ndemoSelect.onchange=()=>loadDemoStation(Number(demoSelect.value));\ndocument.getElementById('demo-power').onchange=event=>{\n  if(demoMode==='tour'&&demoStation===1&&state==='play'){\n    player.power=Number(event.currentTarget.value);player.jumps=0;canvas.focus();\n  }\n};\ndocument.getElementById('demo-retry').onclick=()=>loadDemoStation(demoStation);\ndocument.getElementById('demo-next').onclick=nextDemo;\n\nasync function startSession(mode,station=0){\n  if(mode&&!SQ_PAID){sqUpgrade();return;}sqDeaths=0;\n  unlockSound();\n  demoMode=mode;demoStation=station;\n  showInstructions=document.getElementById('show-instructions').checked;\n  level=0;escapes=0;resetAnswers();randomizeTraps();reset();\n  stageTools.hidden=false;stage.classList.add('expanded');\n  demoToolbar.hidden=!mode;stage.classList.toggle('demo',!!mode);\n  if(stage.requestFullscreen){\n    try{await stage.requestFullscreen();}catch{/* Keep the viewport-sized stage. */}\n  }\n  if(state!=='ready'||stageTools.hidden)return;\n  if(mode==='tour')loadDemoStation(station);\n  else if(showInstructions)showIntro(0);\n  else resumePlay();\n}\nfunction chooseCharacter(name,button){\n  character=name;\n  for(const option of roster.children)option.setAttribute('aria-pressed',String(option===button));\n  return startSession(null);\n}\ndocument.getElementById('demo-level').onclick=()=>startSession('tour');\ndocument.getElementById('demo-maze').onclick=()=>startSession('tour',mazeStation);\nasync function exitStage(withReport=true){\n  if(!stage.classList.contains('expanded'))return;\n  const run=demoMode==='tour'?'Demo Mode \u00b7 '+demoStations[demoStation].name:'Level reached: '+(level+1)+' / '+levels.length;\n  const stats=run+' \u00b7 Tasks completed: '+score/10+' \u00b7 Hyperfocus mazes escaped: '+escapes;\n  state='ready';maze=null;clearControls();lesson.hidden=true;stageTools.hidden=true;\n  stage.classList.remove('expanded','maze','demo');demoToolbar.hidden=true;\n  if(document.fullscreenElement===stage){try{await document.exitFullscreen();}catch{}}\n  if(withReport)openReport(stats);\n  else roster.querySelector('[aria-pressed=\"true\"]')?.focus();\n}\ndocument.getElementById('exit').onclick=()=>exitStage(true);\ndocument.getElementById('sound').onclick=event=>{\n  soundEnabled=!soundEnabled;\n  if(soundEnabled)unlockSound();\n  event.currentTarget.textContent=soundEnabled?'Effects on':'Effects off';\n  event.currentTarget.setAttribute('aria-pressed',String(soundEnabled));\n  canvas.focus();\n};\ndocument.getElementById('music').onclick=event=>{\n  musicEnabled=!musicEnabled;\n  if(musicEnabled)unlockSound();\n  event.currentTarget.textContent=musicEnabled?'Music on':'Music off';\n  event.currentTarget.setAttribute('aria-pressed',String(musicEnabled));\n  musicLoop();canvas.focus();\n};\ndocument.addEventListener('fullscreenchange',()=>{\n  if(document.fullscreenElement===stage)nativeFullscreen=true;\n  else if(nativeFullscreen){\n    nativeFullscreen=false;\n    if(stage.classList.contains('expanded'))exitStage(true);\n  }\n});\ndocument.addEventListener('keydown',event=>{\n  if(event.key==='Escape'&&stage.classList.contains('expanded')&&!document.fullscreenElement)exitStage();\n  if(event.key==='Tab'&&!lesson.hidden){\n    const buttons=skipButton.hidden?[nextButton]:[nextButton,skipButton];\n    const index=buttons.indexOf(document.activeElement);\n    event.preventDefault();\n    buttons[(index+(event.shiftKey?-1:1)+buttons.length)%buttons.length].focus();\n  }\n});\nfor(const name of characters){\n  const button=document.createElement('button');button.title=name;button.setAttribute('aria-label','Play as '+name);\n  button.setAttribute('aria-pressed',String(name===character));\n  const img=document.createElement('img');img.src=assets[name+'Portrait'];img.alt='';button.append(img);\n  button.onclick=()=>chooseCharacter(name,button);roster.append(button);\n}\ncanvas.onclick=()=>canvas.focus();\nreset();\nlet last=null,lag=0;\nfunction frame(now){\n  if(last!==null)lag+=Math.min(50,now-last);last=now;\n  while(lag>=1000/60){step();lag-=1000/60;}\n  render();musicLoop();requestAnimationFrame(frame);\n}\n\nfunction sqUpgrade(){parent.postMessage({type:'side-quest-upgrade'},'*');}\nfunction sqSnapshot(){return {format:'side-quest',version:1,board:{type:'side-quest',title:'My Side Quest',character,stats:{level:level+1,tasks:Math.max(0,score/10),escapes,deaths:sqDeaths},answers:fields.map(({inputs,other})=>({selected:inputs.filter(i=>i.checked).map(i=>i.value),other:other?.value.slice(0,500)||''}))}};}\nfunction sqSend(){parent.postMessage({type:'side-quest-snapshot',payload:sqSnapshot()},'*');}\ndocument.getElementById('reflection').addEventListener('input',sqSend);\nconst cloudSave=document.createElement('button');cloudSave.type='button';cloudSave.textContent=SQ_PAID?'Save stats & responses as a board':'Unlock More Levels';cloudSave.onclick=()=>{if(SQ_PAID){sqSend();report.close();parent.postMessage({type:'side-quest-save'},'*');}else sqUpgrade();};report.querySelector('.actions').append(cloudSave);\naddEventListener('message',e=>{if(e.source!==parent)return;if(e.data?.type==='side-quest-review'&&SQ_PAID){const b=e.data.payload?.board;if(!b)return;character=b.character;level=Math.min(levels.length-1,Math.max(0,b.stats.level-1));score=b.stats.tasks*10;escapes=b.stats.escapes;sqDeaths=b.stats.deaths;fields.forEach((f,i)=>{f.inputs.forEach(input=>input.checked=b.answers[i].selected.includes(input.value));if(f.other){f.other.value=b.answers[i].other;f.other.hidden=!f.inputs.at(-1).checked;f.other.disabled=f.other.hidden;}});openReport('Saved scorecard \u00b7 Level '+b.stats.level+' \u00b7 Tasks completed: '+b.stats.tasks+' \u00b7 Deaths: '+b.stats.deaths+' \u00b7 Mazes escaped: '+b.stats.escapes);}});\nif(!SQ_PAID)document.querySelector('.demo-picker').hidden=true;\nparent.postMessage({type:'side-quest-ready'},'*');\n\nrequestAnimationFrame(frame);\n</script></html>\n";
